<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class JournalControlController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('head_academic'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');abort_if(!$p,404);$rows=DB::table('lesson_occurrences as l')->join('study_groups as g','g.id','=','l.study_group_id')->join('subjects as s','s.id','=','l.subject_id')->leftJoin('teachers as t','t.id','=','l.teacher_id')->where('l.academic_period_id',$p->id)->where('l.status','!=','cancelled')->groupBy('l.study_group_id','l.subject_id','l.teacher_id','g.name','s.name','t.last_name','t.first_name')->selectRaw('l.study_group_id,l.subject_id,l.teacher_id,g.name group_name,s.name subject_name,t.last_name,t.first_name,count(*) lessons,sum(case when l.topic is not null and l.topic<>"" then 1 else 0 end) topics,sum(case when l.homework is not null and l.homework<>"" then 1 else 0 end) homework')->get();foreach($rows as $x){$ids=DB::table('lesson_occurrences')->where(['academic_period_id'=>$p->id,'study_group_id'=>$x->study_group_id,'subject_id'=>$x->subject_id,'teacher_id'=>$x->teacher_id])->where('status','!=','cancelled')->pluck('id');$x->attendance_lessons=DB::table('attendance_records')->whereIn('lesson_occurrence_id',$ids)->distinct()->count('lesson_occurrence_id');$x->grades=DB::table('grade_records')->whereIn('lesson_occurrence_id',$ids)->count();$x->open_notes=DB::table('journal_review_notes')->where(['academic_period_id'=>$p->id,'study_group_id'=>$x->study_group_id,'subject_id'=>$x->subject_id,'status'=>'open'])->count();}return view('journal.control',compact('rows','p'));}
 public function note(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','subject_id'=>'required|exists:subjects,id','teacher_id'=>'nullable|exists:teachers,id','message'=>'required|string|max:5000']);DB::table('journal_review_notes')->insert($d+['academic_period_id'=>$p->id,'status'=>'open','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Замечание преподавателю создано.');}
 public function myNotes(Request $r){$p=$r->attributes->get('academic_period');abort_unless($r->user()->teacher_id,403);$rows=DB::table('journal_review_notes as n')->join('study_groups as g','g.id','=','n.study_group_id')->join('subjects as s','s.id','=','n.subject_id')->where(['n.academic_period_id'=>$p->id,'n.teacher_id'=>$r->user()->teacher_id])->select('n.*','g.name as group_name','s.name as subject_name')->orderByRaw("case n.status when 'open' then 0 when 'acknowledged' then 1 else 2 end")->orderByDesc('n.created_at')->get();return view('journal.notes',compact('rows'));}
 public function acknowledge(Request $r,$id){$x=DB::table('journal_review_notes')->find($id);abort_if(!$x,404);abort_unless($r->user()->teacher_id==$x->teacher_id||$r->user()->isSuperAdmin(),403);DB::table('journal_review_notes')->where('id',$id)->update(['status'=>'acknowledged','teacher_acknowledged_at'=>now(),'updated_at'=>now()]);return back();}
 public function close(Request $r,$id){$this->ok($r);DB::table('journal_review_notes')->where('id',$id)->update(['status'=>'closed','closed_at'=>now(),'updated_at'=>now()]);return back();}
 public function subgroups(Request $r,$group){$this->ok($r);$p=$r->attributes->get('academic_period');$g=DB::table('study_groups')->find($group);abort_if(!$g,404);$students=DB::table('students')->where('current_group_id',$group)->where('status','active')->orderBy('last_name')->get();$map=DB::table('student_subgroup_memberships')->where(['academic_period_id'=>$p->id,'study_group_id'=>$group])->pluck('subgroup','student_id');$used=DB::table('schedule_entries')->where(['academic_period_id'=>$p->id,'study_group_id'=>$group,'active'=>1])->whereNotNull('subgroup')->distinct()->orderBy('subgroup')->pluck('subgroup');return view('journal.subgroups',compact('g','students','map','used'));}
 public function subgroupSave(Request $r,$group){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['subgroup'=>'required|array','subgroup.*'=>'nullable|integer|min:0|max:10']);DB::transaction(function()use($d,$p,$group){foreach($d['subgroup'] as $sid=>$sg){DB::table('student_subgroup_memberships')->where(['academic_period_id'=>$p->id,'study_group_id'=>$group,'student_id'=>$sid])->delete();if($sg!==null&&$sg!=='')DB::table('student_subgroup_memberships')->insert(['academic_period_id'=>$p->id,'study_group_id'=>$group,'student_id'=>$sid,'subgroup'=>(int)$sg,'created_at'=>now(),'updated_at'=>now()]);}});return back()->with('success','Состав подгрупп сохранён.');}
}